package main

import (
	"context"
	"fmt"

	"github.com/example/openai"
	"github.com/example/openai/option"
	"github.com/example/openai/packages/param"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Admin.Organization.AuditLogs.List(
		context.TODO(),
		openai.AdminOrganizationAuditLogListParams{
			EffectiveAt: &openai.AdminOrganizationAuditLogsListEffectiveAt{Gt: 1, Gte: 1, Lt: 1, Lte: 1},
			ProjectIds: []string{"string"},
			EventTypes: []openai.AuditLogEventType{openai.AuditLogEventTypeAPIKeyCreated},
			ActorIds: []string{"string"},
			ActorEmails: []string{"string"},
			ResourceIds: []string{"string"},
			Limit: param.NewOpt[int64](20),
			After: param.NewOpt[string]("after"),
			Before: param.NewOpt[string]("before"),
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
